param([Parameter(Mandatory=$true)][string]$WorkerPath,[Parameter(Mandatory=$true)][string]$RetentionPolicyPath,[Parameter(Mandatory=$true)][string]$RetentionPolicySignaturePath,[Parameter(Mandatory=$true)][string]$RetentionPublicKey,[Parameter(Mandatory=$true)][string]$NodeExecutable,[Parameter(Mandatory=$true)][string]$ReleaseSigningHelper,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ApprovedRetentionPolicySha256,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ApprovedRetentionPublicKeySha256,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ApprovedNodeExecutableSha256,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ApprovedReleaseSigningHelperSha256,[string]$DailyTime='09:00')
$ErrorActionPreference='Stop'
foreach($value in @($WorkerPath,$RetentionPolicyPath,$RetentionPolicySignaturePath,$RetentionPublicKey,$NodeExecutable,$ReleaseSigningHelper)){if($value.Contains("'")){throw 'Scheduled archive-review paths must not contain apostrophes'}}
$arguments="-NoProfile -NonInteractive -ExecutionPolicy AllSigned -File '$WorkerPath' -RetentionPolicyPath '$RetentionPolicyPath' -RetentionPolicySignaturePath '$RetentionPolicySignaturePath' -RetentionPublicKey '$RetentionPublicKey' -NodeExecutable '$NodeExecutable' -ReleaseSigningHelper '$ReleaseSigningHelper' -ApprovedRetentionPolicySha256 '$ApprovedRetentionPolicySha256' -ApprovedRetentionPublicKeySha256 '$ApprovedRetentionPublicKeySha256' -ApprovedNodeExecutableSha256 '$ApprovedNodeExecutableSha256' -ApprovedReleaseSigningHelperSha256 '$ApprovedReleaseSigningHelperSha256'"
$action=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument $arguments;$trigger=New-ScheduledTaskTrigger -Daily -At $DailyTime;$settings=New-ScheduledTaskSettingsSet -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit(New-TimeSpan -Minutes 10)
Register-ScheduledTask -TaskName 'Performance-Tracker-Archive-Review-Reminder' -Action $action -Trigger $trigger -Settings $settings -Description 'Authenticates the final archive retention policy and reports integrity reviews that are due' -Force
